mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM sql_task_version
WHERE task_id = #{taskId}

SELECT id, task_id, version_no, base_effective_version_no, base_effective_checksum, name, description, parameter_schema, sql_checksum, version_note, status, revision, created_by, updated_by, effective_by, effective_time, create_time, update_time FROM sql_task_version WHERE task_id = #{taskId}
AND (CAST(version_no AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(version_note, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(updated_by, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(created_by, '') LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY version_no DESC LIMIT #{offset}, #{pageSize}
